package main

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shiraz Phone</title>
<style>
:root{font-family:system-ui,sans-serif;color:#e8e8e8;background:#000;color-scheme:dark}
*{box-sizing:border-box}html{height:100%;overflow:hidden;background:#000}body{margin:0;height:100%;overflow:hidden;background:#000;line-height:1.7;-webkit-font-smoothing:antialiased}
button,input{font:inherit}button:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid #fff;outline-offset:3px}
main{width:100%;height:100vh;height:100dvh;overflow:hidden}
.status{display:inline-flex;align-items:center;border:1px solid #303743;border-radius:99px;padding:7px 11px;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#a9b4c2;white-space:nowrap}.status:before{content:'';display:inline-block;width:6px;height:6px;background:#666;border-radius:50%;margin-right:9px;vertical-align:2px}.status.online:before{background:#d8e6ff;box-shadow:0 0 8px #d8e6ff80}
.layout{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));height:100%;min-height:0;overflow:hidden}.phone-stage{height:100%;min-height:0;display:grid;place-items:center;padding:24px;border-right:1px solid #242424}.workspace{height:100%;min-height:0;overflow-x:hidden;overflow-y:auto;overscroll-behavior-y:contain;scrollbar-gutter:stable;display:flex;flex-direction:column;justify-content:flex-start;padding:clamp(28px,4vw,58px) clamp(28px,5vw,72px);background:#060708}
.phone{width:min(100%,390px,calc(52vh - 50px));margin:auto;padding:10px;border:1px solid #4c4c4c;border-radius:20px;background:#080808;box-shadow:0 0 0 4px #151515,0 26px 80px #000;position:relative}.screen{position:relative;aspect-ratio:9/16;overflow:hidden;background:#0c0c0c;border-radius:12px;touch-action:none;user-select:none}.screen video{display:block;width:100%;height:100%;object-fit:fill;visibility:hidden}.screen.ready video{visibility:visible}.empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:30px;color:#777;font-size:13px}.empty .icon{font-size:32px;font-weight:200;color:#bdbdbd;margin-bottom:20px}.empty strong{color:#f2f2f2;font-size:18px;font-weight:450;margin-bottom:7px}.screen.ready .empty{display:none}.nav{height:40px;display:flex;align-items:center;justify-content:space-around}.nav button{border:0;background:none;color:#aaa;font-size:23px;cursor:pointer;width:52px;height:36px;line-height:1}.nav button:hover{color:#fff}

.panel{width:100%;max-width:620px;margin:auto}.portal-top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:26px}.eyebrow{font-size:10px;letter-spacing:1.4px;text-transform:uppercase;color:#7f8893;margin:0}.session-label,.section-label{font-size:10px;letter-spacing:1.2px;text-transform:uppercase;color:#85909d;font-weight:600}.session{padding:27px 28px;background:linear-gradient(145deg,#111821,#0a0d11 65%);border:1px solid #29313b;border-radius:12px}.session h2{font-size:clamp(27px,3vw,38px);font-weight:500;letter-spacing:-1.1px;line-height:1.2;color:#f2f4f7;margin:12px 0 8px;overflow-wrap:anywhere}.session p{color:#9ba7b3;font-size:13px;line-height:1.6;margin:0}.session-facts{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:24px;padding-top:18px;border-top:1px solid #26313b}.session-facts small{display:block;color:#788491;font-size:10px;text-transform:uppercase;letter-spacing:.8px}.session-facts strong{display:block;color:#d8e1ea;font-size:12px;font-weight:500;margin-top:4px}.section{border:1px solid #24292f;background:#0b0d10;border-radius:10px;padding:20px 22px;margin-top:16px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.section-head small{font-size:11px;color:#687481}.actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.actions button{border:1px solid #343c45;background:#141a20;color:#e0e6ed;border-radius:5px;padding:10px 12px;text-align:left;cursor:pointer;font-size:12px}.actions button:hover{background:#202a34}.actions button:disabled{opacity:.4;cursor:not-allowed}.actions .danger{border-color:#513638;color:#e8b9ba}.section input[type=file]{display:block;width:100%;border:1px solid #343c45;border-radius:5px;background:#11161b;color:#d2dce6;padding:11px;font-size:12px}.section input[type=file]::file-selector-button{color:#eee;background:#26303a;border:1px solid #3b4753;border-radius:3px;padding:6px 10px;margin-right:10px;cursor:pointer}.primary{background:#e8edf2;border:1px solid #e8edf2;border-radius:4px;color:#0a0d10;font-size:12px;font-weight:600;padding:10px 15px;margin-top:14px;cursor:pointer}.primary:hover{background:#cbd6e0}.primary:disabled{opacity:.45;cursor:not-allowed}.logs{margin-top:16px;border:1px solid #24292f;background:#0b0d10;border-radius:10px;padding:16px 22px}.logs summary{cursor:pointer;color:#aeb8c2;font-size:12px}.logs pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:250px;overflow:auto;background:#080a0c;border:1px solid #24292f;border-radius:5px;padding:14px;color:#aab4be;font-size:11px;line-height:1.5}

footer{max-width:620px;width:100%;margin:30px auto 0;border-top:1px solid #242424;padding:18px 0;font-size:11px;color:#606060;display:flex;justify-content:space-between;gap:20px}footer a{color:#aaa;text-decoration:none}footer a:hover{color:#fff}
@media(max-width:760px){html,body{height:auto;overflow:auto}main{height:auto;min-height:100vh;overflow:visible}.layout{height:auto;min-height:100vh;overflow:visible;grid-template-columns:1fr}.phone-stage{height:auto;min-height:0;padding:36px 24px;border-right:0;border-bottom:1px solid #242424}.workspace{height:auto;min-height:0;overflow:visible;padding:36px 24px}.phone{width:min(100%,345px)}.panel{padding:0}.portal-top{margin-bottom:18px}.session{padding:22px}.session h2{font-size:30px}.section{padding:18px}footer{margin-top:44px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body><main><div class="layout"><div class="phone-stage"><div class="phone"><div id="screen" class="screen"><video id="frame" autoplay playsinline muted aria-label="Live Android app screen"></video><div class="empty"><div class="icon">◇</div><strong>Your app appears here</strong><span>Upload an APK to start the phone.</span></div></div><div class="nav"><button id="back" title="Back" aria-label="Back">‹</button><button id="stop" title="Stop app" aria-label="Stop app">○</button><button id="refresh" title="Refresh screen" aria-label="Refresh screen">↻</button></div></div></div><div class="workspace"><section class="panel"><div class="portal-top"><p class="eyebrow">SHIRAZ / DEVICE PORTAL</p><span id="status" class="status" role="status" aria-live="polite">Connecting</span></div><div class="session"><span class="session-label">Current app</span><h2 id="app-name">No app running</h2><p id="app-note">Upload an APK to start a session on this device.</p><div class="session-facts"><div><small>Display</small><strong>360 × 640</strong></div><div><small>Input</small><strong>Touch + keyboard</strong></div></div></div><div class="section"><div class="section-head"><span class="section-label">Device controls</span><small>Live session</small></div><div class="actions"><button id="portal-back" type="button" disabled>Back</button><button id="portal-enter" type="button" disabled>Enter</button><button id="portal-refresh" type="button" disabled>Refresh screen</button><button id="portal-stop" class="danger" type="button" disabled>Stop session</button></div></div><form id="form" class="section"><div class="section-head"><label for="apk" class="section-label">Launch an APK</label><small>Choose a file</small></div><input id="apk" name="apk" type="file" accept=".apk,application/vnd.android.package-archive" required><button class="primary" id="send" disabled>Upload and run</button></form><div class="logs"><details><summary>Run log</summary><pre id="log"></pre></details></div></section><footer><span>SpectreOSS / Shiraz · Experimental</span><a href="https://spectre-oss.github.io/">Back to SpectreOSS ↗</a></footer></div></div></main>
<script>
const status=document.querySelector('#status'),screen=document.querySelector('#screen'),frame=document.querySelector('#frame'),send=document.querySelector('#send'),log=document.querySelector('#log'),appName=document.querySelector('#app-name'),appNote=document.querySelector('#app-note');
let peer,channel,connected=false,hover=false,drag=false,reconnecting=false,videoReady=false,appActive=false,lastMove=0;const held=new Set();
function setStatus(message,online){status.textContent=message;status.classList.toggle('online',online)}
function setApp(name){appName.textContent=name||'No app running';appNote.textContent=name?'Use the phone screen or device controls to interact with this app.':'Upload an APK to start a session on this device.'}
function setRunning(active){appActive=active;screen.classList.toggle('ready',active&&videoReady);send.disabled=!connected||active;for(const id of ['portal-back','portal-enter','portal-refresh','portal-stop'])document.getElementById(id).disabled=!connected||!active}
function input(action,x=0,y=0,key='',text=''){if(channel?.readyState==='open')channel.send(JSON.stringify({action,x,y,key,text}))}
function releaseKeys(){for(const key of held)input('keyup',0,0,key);held.clear()}
function retry(){if(reconnecting)return;reconnecting=true;connected=false;videoReady=false;frame.srcObject=null;setRunning(false);releaseKeys();setStatus('Reconnecting',false);peer?.close();setTimeout(()=>{reconnecting=false;connect()},1600)}
async function connect(){try{
 peer=new RTCPeerConnection({iceServers:[]});channel=peer.createDataChannel('control');peer.addTransceiver('video',{direction:'recvonly'});
 channel.onopen=()=>{connected=true;setRunning(appActive);setStatus('Connected',true)};
 channel.onmessage=e=>{const msg=JSON.parse(e.data);if(msg.type==='app'){setApp(msg.message)}else if(msg.type==='status'){const active=/^(Running|Starting|APK accepted)/i.test(msg.message);setRunning(active);setStatus(msg.message,true);if(msg.message==='Ready'||msg.message.startsWith('Shiraz exited'))setApp('')}else{log.textContent+=msg.message+'\n';log.scrollTop=log.scrollHeight;if(msg.type==='error'){setRunning(false);setStatus('Run failed',false)}}};
 const currentPeer=peer;currentPeer.ontrack=e=>{if(currentPeer!==peer)return;frame.srcObject=new MediaStream([e.track]);frame.play().catch(()=>{})};frame.onplaying=()=>{videoReady=true;screen.classList.toggle('ready',appActive)};
 currentPeer.onconnectionstatechange=()=>{if(currentPeer!==peer)return;if(['failed','closed'].includes(currentPeer.connectionState))retry();if(currentPeer.connectionState==='disconnected')setTimeout(()=>{if(currentPeer===peer&&currentPeer.connectionState==='disconnected')retry()},3000)};
 const offer=await peer.createOffer();await peer.setLocalDescription(offer);
 if(peer.iceGatheringState!=='complete')await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('ICE gathering timed out')),15000);peer.addEventListener('icegatheringstatechange',()=>{if(peer.iceGatheringState==='complete'){clearTimeout(timeout);resolve()}},{once:false})});
 const response=await fetch('/webrtc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(peer.localDescription)});
 if(!response.ok)throw Error(await response.text());await peer.setRemoteDescription(await response.json());
 }catch(error){log.textContent+=error.message+'\n';retry()}}
 connect();function point(e){const r=screen.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
 screen.addEventListener('pointerenter',()=>{hover=true});screen.addEventListener('pointerleave',()=>{hover=false;releaseKeys()});window.addEventListener('blur',()=>{hover=false;releaseKeys()});
 window.addEventListener('keydown',e=>{if(!hover||!connected)return;e.preventDefault();if(!held.has(e.code)){held.add(e.code);input('keydown',0,0,e.code)}if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey)input('text',0,0,'',e.key)});
 window.addEventListener('keyup',e=>{if(!held.has(e.code))return;e.preventDefault();held.delete(e.code);input('keyup',0,0,e.code)});
 screen.addEventListener('pointerdown',e=>{if(!screen.classList.contains('ready'))return;drag=true;screen.setPointerCapture(e.pointerId);const p=point(e);input('fingerdown',p.x,p.y)});screen.addEventListener('pointermove',e=>{if(drag&&performance.now()-lastMove>50){lastMove=performance.now();const p=point(e);input('fingermove',p.x,p.y)}});function end(e){if(drag){drag=false;const p=point(e);input('fingerup',p.x,p.y)}}screen.addEventListener('pointerup',end);screen.addEventListener('pointercancel',end);document.querySelector('#back').onclick=document.querySelector('#portal-back').onclick=()=>input('back');document.querySelector('#stop').onclick=document.querySelector('#portal-stop').onclick=()=>input('stop');document.querySelector('#refresh').onclick=document.querySelector('#portal-refresh').onclick=()=>{frame.play().catch(()=>{})};document.querySelector('#portal-enter').onclick=()=>input('enter');
 document.querySelector('#form').onsubmit=async e=>{e.preventDefault();send.disabled=true;log.textContent='';setApp(document.querySelector('#apk').files[0]?.name||'');setStatus('Uploading',true);try{const response=await fetch('/upload',{method:'POST',body:new FormData(e.target)});if(!response.ok)throw Error((await response.text()).trim());setRunning(true);setStatus('Starting',true)}catch(error){setRunning(false);setStatus('Upload failed',false);log.textContent=error.message}finally{send.disabled=!connected||appActive}};
</script></body></html>`
